-- Focus Session 2.0 / Phase 2: additive schema only.
-- Copy into the timestamped file generated by: supabase migration new focus_v2_data_model
-- Do not edit existing migration files and do not run this directly on production.
begin;

-- Old sessions remain legacy. Do not backfill or rewrite their timestamps/metrics.
alter table public.focus_sessions
  add column session_mode text not null default 'legacy';
alter table public.focus_sessions
  add constraint focus_sessions_session_mode_check
  check (session_mode in ('legacy', 'pomodoro'));

-- Activation gate: while the web app is still legacy-only, authenticated callers
-- cannot insert or mutate a Pomodoro parent without a plan. Phase 3 explicitly
-- removes these gates only together with production-ready lifecycle RPCs.
create policy focus_v2_legacy_only_insert
on public.focus_sessions as restrictive
for insert to authenticated with check (session_mode = 'legacy');
create policy focus_v2_legacy_only_update
on public.focus_sessions as restrictive
for update to authenticated
using (session_mode = 'legacy') with check (session_mode = 'legacy');

-- Per-user defaults. This is NOT a snapshot; sessions copy values into a plan.
create table public.focus_user_preferences (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  focus_minutes integer not null default 25 check (focus_minutes between 5 and 120),
  short_break_minutes integer not null default 5 check (short_break_minutes between 1 and 30),
  long_break_minutes integer not null default 15 check (long_break_minutes between 5 and 60),
  round_count integer not null default 4 check (round_count between 1 and 8),
  long_break_every integer not null default 4 check (long_break_every between 2 and 8),
  auto_start_breaks boolean not null default false,
  auto_start_focus boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger focus_user_preferences_set_updated_at
before update on public.focus_user_preferences
for each row execute function public.set_updated_at();

-- Immutable configuration snapshot of one Pomodoro parent session.
-- No rows here for legacy sessions.
create table public.focus_session_plans (
  session_id uuid primary key references public.focus_sessions(id) on delete cascade,
  focus_minutes integer not null check (focus_minutes between 5 and 120),
  short_break_minutes integer not null check (short_break_minutes between 1 and 30),
  long_break_minutes integer not null check (long_break_minutes between 5 and 60),
  round_count integer not null check (round_count between 1 and 8),
  long_break_every integer not null check (long_break_every between 2 and 8),
  auto_start_breaks boolean not null,
  auto_start_focus boolean not null,
  config_version smallint not null default 1 check (config_version = 1),
  created_at timestamptz not null default now()
);

-- Never allow a Pomodoro plan on a legacy/terminated parent or with
-- a parent planned_minutes value that disagrees with focus-only minutes.
create function public.focus_v2_check_plan()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  parent public.focus_sessions%rowtype;
begin
  select * into parent
  from public.focus_sessions
  where id = new.session_id;
  if not found or parent.session_mode <> 'pomodoro'
     or parent.status <> 'ongoing'
     or parent.planned_minutes <> new.focus_minutes * new.round_count then
    raise exception using errcode = '23514', message = 'Invalid Pomodoro parent or focus-only planned_minutes';
  end if;
  return new;
end;
$$;
create trigger focus_v2_plan_guard
before insert or update on public.focus_session_plans
for each row execute function public.focus_v2_check_plan();

-- One row per scheduled Focus or Break segment, pre-created at session creation.
-- Position: 1 focus round 1, 2 break, 3 focus round 2, etc.; no break after the final focus.
create table public.focus_session_segments (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.focus_session_plans(session_id) on delete cascade,
  position integer not null check (position between 1 and 15),
  round_number integer not null check (round_number between 1 and 8),
  segment_kind text not null check (segment_kind in ('focus', 'short_break', 'long_break')),
  planned_seconds integer not null check (planned_seconds between 60 and 7200),
  status text not null default 'pending'
    check (status in ('pending', 'running', 'paused', 'completed', 'skipped', 'interrupted')),
  started_at timestamptz,
  paused_at timestamptz,
  ended_at timestamptz,
  total_paused_seconds integer not null default 0 check (total_paused_seconds >= 0),
  actual_seconds integer not null default 0 check (actual_seconds >= 0 and actual_seconds <= planned_seconds),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (session_id, position),
  constraint focus_v2_segment_position_matches_round check (
    (segment_kind = 'focus' and position = 2 * round_number - 1) or
    (segment_kind in ('short_break', 'long_break') and position = 2 * round_number)
  ),
  constraint focus_v2_segment_temporal_integrity check (
    (status = 'pending' and started_at is null and paused_at is null
      and ended_at is null and actual_seconds = 0 and total_paused_seconds = 0)
    or (status = 'running' and started_at is not null and paused_at is null and ended_at is null)
    or (status = 'paused' and started_at is not null and paused_at is not null
      and paused_at >= started_at and ended_at is null)
    or (status = 'completed' and started_at is not null
      and ended_at is not null and paused_at is null and ended_at >= started_at)
    or (status in ('skipped', 'interrupted') and ended_at is not null
      and paused_at is null and (started_at is null or ended_at >= started_at))
  )
);
create trigger focus_v2_segments_set_updated_at
before update on public.focus_session_segments
for each row execute function public.set_updated_at();
-- The UNIQUE(session_id, position) constraint already provides a lookup index.
create unique index one_live_focus_v2_segment_per_session
  on public.focus_session_segments (session_id)
  where status in ('running', 'paused');

-- Each segment must match the immutable snapshot (duration, kind, round number).
create function public.focus_v2_check_segment()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  cfg public.focus_session_plans%rowtype;
  expected_kind text;
  expected_seconds integer;
begin
  select * into cfg from public.focus_session_plans
  where session_id = new.session_id;
  if not found or new.round_number > cfg.round_count
     or new.position > 2 * cfg.round_count - 1 then
    raise exception using errcode = '23514', message = 'Invalid Pomodoro segment position';
  end if;
  if mod(new.position, 2) = 1 then
    expected_kind := 'focus';
    expected_seconds := cfg.focus_minutes * 60;
  elsif mod(new.round_number, cfg.long_break_every) = 0 then
    expected_kind := 'long_break';
    expected_seconds := cfg.long_break_minutes * 60;
  else
    expected_kind := 'short_break';
    expected_seconds := cfg.short_break_minutes * 60;
  end if;
  if new.segment_kind <> expected_kind or new.planned_seconds <> expected_seconds then
    raise exception using errcode = '23514', message = 'Segment differs from Pomodoro plan';
  end if;
  if tg_op = 'UPDATE' then
    if new.session_id is distinct from old.session_id
       or new.position is distinct from old.position
       or new.round_number is distinct from old.round_number
       or new.segment_kind is distinct from old.segment_kind
       or new.planned_seconds is distinct from old.planned_seconds then
      raise exception using errcode = '23514', message = 'Pomodoro segment identity is immutable';
    end if;
  end if;
  return new;
end;
$$;
create trigger focus_v2_segment_guard
before insert or update on public.focus_session_segments
for each row execute function public.focus_v2_check_segment();

-- RLS for all three tables, even when writes are initially gated.
alter table public.focus_user_preferences enable row level security;
alter table public.focus_session_plans enable row level security;
alter table public.focus_session_segments enable row level security;

create policy focus_preferences_select on public.focus_user_preferences
for select to authenticated using (user_id = (select auth.uid()));
create policy focus_preferences_insert on public.focus_user_preferences
for insert to authenticated with check (user_id = (select auth.uid()));
create policy focus_preferences_update on public.focus_user_preferences
for update to authenticated
using (user_id = (select auth.uid()))
with check (user_id = (select auth.uid()));

create policy focus_plans_select on public.focus_session_plans
for select to authenticated using (
  exists (select 1 from public.focus_sessions fs
          where fs.id = session_id and fs.user_id = (select auth.uid()))
);
create policy focus_plans_insert on public.focus_session_plans
for insert to authenticated with check (
  exists (select 1 from public.focus_sessions fs
          where fs.id = session_id and fs.user_id = (select auth.uid())
            and fs.session_mode = 'pomodoro')
);

create policy focus_segments_select on public.focus_session_segments
for select to authenticated using (
  exists (select 1 from public.focus_sessions fs
          where fs.id = session_id and fs.user_id = (select auth.uid()))
);
create policy focus_segments_insert on public.focus_session_segments
for insert to authenticated with check (
  exists (select 1 from public.focus_sessions fs
          where fs.id = session_id and fs.user_id = (select auth.uid())
            and fs.session_mode = 'pomodoro')
);
create policy focus_segments_update on public.focus_session_segments
for update to authenticated
using (exists (select 1 from public.focus_sessions fs
              where fs.id = session_id and fs.user_id = (select auth.uid())))
with check (exists (select 1 from public.focus_sessions fs
                   where fs.id = session_id and fs.user_id = (select auth.uid())));

-- Explicit privileges: preferences are editable, plans/segments READ ONLY
-- until Phase 3 adds transactional RPCs and enables their write permissions.
revoke all on public.focus_user_preferences from anon, authenticated;
revoke all on public.focus_session_plans from anon, authenticated;
revoke all on public.focus_session_segments from anon, authenticated;
grant select, insert, update on public.focus_user_preferences to authenticated;
grant select on public.focus_session_plans, public.focus_session_segments to authenticated;
grant all on public.focus_user_preferences, public.focus_session_plans,
  public.focus_session_segments to service_role;
revoke all on function public.focus_v2_check_plan() from public, anon, authenticated;
revoke all on function public.focus_v2_check_segment() from public, anon, authenticated;

commit;
